#!/usr/bin/env python3
import socket, time, threading, sys

HOST, PORT = "127.0.0.1", 4562
cmds = sys.argv[1:]  # commands to send, each after a delay

buf = bytearray()
lock = threading.Lock()
def reader(s):
    while True:
        try:
            d = s.recv(65536)
        except Exception:
            break
        if not d:
            break
        with lock:
            buf.extend(d)

s = socket.create_connection((HOST, PORT), timeout=10)
t = threading.Thread(target=reader, args=(s,), daemon=True)
t.start()

def dump(tag):
    with lock:
        data = bytes(buf)
        buf.clear()
    sys.stdout.write(f"\n----[{tag}] {len(data)}B----\n")
    sys.stdout.write(data.decode('latin1'))
    sys.stdout.flush()

time.sleep(8)
dump("banner/initial")
for c in cmds:
    sys.stdout.write(f"\n>>> SEND {c!r}\n"); sys.stdout.flush()
    s.sendall((c + "\n").encode())
    time.sleep(10)
    dump(c)
time.sleep(3)
dump("final")
s.close()

