#!/usr/bin/env python3
# Live-oracle probe for cross-confirmation ONLY. Keeps one TCP session open,
# sends the console protocol line-by-line, prints every response verbatim.
import socket, time, threading, sys

HOST, PORT = "127.0.0.1", 4562
buf = bytearray()
lock = threading.Lock()

def reader(s):
    while True:
        try:
            d = s.recv(65536)
        except Exception:
            break
        if not d:
            break
        with lock:
            buf.extend(d)

def dump(tag):
    time.sleep(0.2)
    with lock:
        data = bytes(buf); buf.clear()
    sys.stdout.write(f"\n----[{tag}] {len(data)}B----\n")
    sys.stdout.write(repr(data.decode('latin1')))
    sys.stdout.write("\n")
    sys.stdout.flush()

def send(s, line, wait=2.0, tag=None):
    sys.stdout.write(f"\n>>> {line!r}\n"); sys.stdout.flush()
    s.sendall((line + "\n").encode())
    time.sleep(wait)
    dump(tag or line)

s = socket.create_connection((HOST, PORT), timeout=10)
threading.Thread(target=reader, args=(s,), daemon=True).start()
time.sleep(3)
dump("banner")

seq = sys.argv[1:]
for c in seq:
    # allow "WAIT:n" pseudo-cmd
    if c.startswith("WAIT:"):
        time.sleep(float(c[5:])); dump("wait"); continue
    send(s, c, wait=2.5)
time.sleep(1)
dump("final")
s.close()

