#!/usr/bin/env python3
# Cross-confirm driver for the live container oracle on 4562.
# Waits for the "CSIRAC> " prompt with long timeouts (qemu is slow).
import socket, time, threading, sys

HOST, PORT = "127.0.0.1", 4562
PROMPT = b"CSIRAC> "

class Reader:
    def __init__(self, s):
        self.s=s; self.buf=bytearray(); self.lock=threading.Lock(); self.alive=True
        threading.Thread(target=self.run, daemon=True).start()
    def run(self):
        while self.alive:
            try: d=self.s.recv(8192)
            except socket.timeout: continue
            except Exception: break
            if not d: self.alive=False; break
            with self.lock: self.buf.extend(d)
    def snap(self):
        with self.lock: return bytes(self.buf)

def pr(b):
    return ''.join(chr(x) if 32<=x<127 else ('\n' if x==10 else '.') for x in b)

def wait_prompt(r, base, timeout):
    t0=time.time()
    while time.time()-t0<timeout:
        tail=r.snap()[base:]
        if tail.count(PROMPT)>=1:
            return True, tail
        if not r.alive: return False, tail
        time.sleep(0.5)
    return False, r.snap()[base:]

def main():
    banner_to=float(sys.argv[1]); cmd_to=float(sys.argv[2]); cmds=sys.argv[3:]
    s=socket.create_connection((HOST,PORT),timeout=10); s.settimeout(1.0)
    r=Reader(s)
    print(f"[connected; waiting banner up to {banner_to}s]",flush=True)
    ok,banner=wait_prompt(r,0,banner_to)
    print(f"=== BANNER ok={ok} ({len(banner)}B) ===\n{pr(banner)}",flush=True)
    base=len(r.snap())
    for c in cmds:
        print(f"\n>>> {c!r}",flush=True)
        s.sendall((c+"\n").encode())
        ok,new=wait_prompt(r,base,cmd_to)
        base=len(r.snap())
        print(f"<<< ok={ok} ({len(new)}B):\n{pr(new)}",flush=True)
    s.close()

main()

