#!/usr/bin/env python3
# Faithful live-oracle driver for the running challenge purr-data on TCP 4562.
# Answer-agnostic: just relays the console protocol and prints every byte received.
# Usage: python3 -I live_oracle.py <banner_wait> <cmd_wait> "CMD1" "CMD2" ...
#   special token "WAIT:n" sleeps n seconds and dumps.
import socket, time, threading, sys, re

HOST, PORT = "127.0.0.1", 4562

class Reader:
    def __init__(self, s):
        self.s=s; self.buf=bytearray(); self.lock=threading.Lock(); self.alive=True
        threading.Thread(target=self.run, daemon=True).start()
    def run(self):
        while self.alive:
            try: d=self.s.recv(65536)
            except socket.timeout: continue
            except Exception: break
            if not d: self.alive=False; break
            with self.lock: self.buf.extend(d)
    def snap(self):
        with self.lock: return bytes(self.buf)

def pr(b):
    # printable rendering preserving newlines
    out=[]
    for x in b:
        if x==10: out.append('\n')
        elif 32<=x<127: out.append(chr(x))
        else: out.append('.')
    return ''.join(out)

def scan(b):
    s=b.decode('latin1')
    hits=[]
    for m in re.finditer(r'csaw\{[^}]*\}', s):
        hits.append(m.group(0))
    chk = "L7USw*KLz'0VI/3)keO#]_}z\":M$tYIFf-HB'c8NwU"
    has_chk = chk in s
    return hits, has_chk

def main():
    banner_to=float(sys.argv[1]); cmd_to=float(sys.argv[2]); cmds=sys.argv[3:]
    s=socket.create_connection((HOST,PORT),timeout=10); s.settimeout(1.0)
    r=Reader(s)
    print(f"[connected; banner wait {banner_to}s]",flush=True)
    time.sleep(banner_to)
    base=0
    snap=r.snap()
    print(f"=== BANNER ({len(snap)}B) ===\n{pr(snap)}\n=== raw repr ===\n{snap[:2000]!r}",flush=True)
    base=len(snap)
    for c in cmds:
        if c.startswith("WAIT:"):
            time.sleep(float(c[5:]))
        else:
            print(f"\n>>> SEND {c!r}",flush=True)
            s.sendall((c+"\n").encode())
            time.sleep(cmd_to)
        snap=r.snap(); new=snap[base:]; base=len(snap)
        hits,chk=scan(new)
        print(f"<<< ({len(new)}B) csaw_hits={hits} checkpoint={chk}\n{pr(new)}",flush=True)
        if new:
            print(f"--- raw repr ---\n{new!r}",flush=True)
    # final drain
    time.sleep(1.0)
    snap=r.snap(); new=snap[base:]
    if new:
        hits,chk=scan(new)
        print(f"\n=== FINAL DRAIN ({len(new)}B) csaw_hits={hits} checkpoint={chk} ===\n{pr(new)}",flush=True)
    s.close()

main()

